	/**
	 * Method to retrieve the TransferOrder via TransferOrderFetchOneSummary
	 * @param 	summary TransferOrderFetchOneSummary
	 * @return 	TransferOrderFetchOneResponse
	 */
	public TransferOrder getTransferOrder( TransferOrderFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TransferOrderFetchOneSummary arg cannot be null" );

		TransferOrder entity = null;
		UUID id = summary.getTransferOrderId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a TransferOrder using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


